import {
  addDaysToKey,
  dateKey,
  daysBetweenKeys,
  parseKey,
  weekdayOfKey,
  zonedTimeToInstant,
} from './time';
import type { EventType, HostSchedule, Instant, Slot } from '../types';

export type { EventType, HostSchedule, Slot };

function hm(value: string): { hour: number; minute: number } {
  const [hour, minute] = value.split(':').map(Number);
  return { hour, minute };
}

/**
 * Slots are generated by resolving each wall-clock start in the host's zone, so
 * a host in a DST zone keeps "9 AM" across their own clock change.
 *
 * All bookable slot starts whose start falls inside [from, to), before
 * removing existing bookings.
 */
export function generateSlots(
  schedule: HostSchedule,
  event: EventType,
  from: Instant,
  to: Instant,
  now: Instant,
): Slot[] {
  const tz = schedule.timeZone;
  const earliest = now + event.minimumNoticeMinutes * 60_000;
  const todayKey = dateKey(tz, now);
  const lastKey = addDaysToKey(todayKey, event.bookingWindowDays);

  // Host calendar days that can overlap the range (±1 day covers any offset).
  const firstKey = addDaysToKey(dateKey(tz, from), -1);
  const endKey = addDaysToKey(dateKey(tz, to), 1);
  const slots: Slot[] = [];
  const seen = new Set<number>();

  for (let key = firstKey; daysBetweenKeys(key, endKey) >= 0; key = addDaysToKey(key, 1)) {
    if (daysBetweenKeys(key, lastKey) < 0) break;
    const ranges = schedule.weekly[weekdayOfKey(key)] ?? [];
    const { year, month, day } = parseKey(key);
    for (const [startText, endText] of ranges) {
      const rangeStart = zonedTimeToInstant(tz, { year, month, day, ...hm(startText) }).instant;
      const rangeEnd = zonedTimeToInstant(tz, { year, month, day, ...hm(endText) }).instant;
      for (let t = rangeStart; t + event.lengthMinutes * 60_000 <= rangeEnd; t += event.lengthMinutes * 60_000) {
        if (t < from || t >= to || t < earliest || seen.has(t)) continue;
        seen.add(t);
        slots.push({ start: t, end: t + event.lengthMinutes * 60_000 });
      }
    }
  }
  return slots.sort((a, b) => a.start - b.start);
}

/** Stable pseudo-random "already booked" marker so the demo calendar looks lived in. */
export function isPreBooked(start: Instant, seed = 7): boolean {
  let h = (Math.floor(start / 60_000) ^ seed) >>> 0;
  h = Math.imul(h ^ (h >>> 16), 0x45d9f3b) >>> 0;
  h = Math.imul(h ^ (h >>> 16), 0x45d9f3b) >>> 0;
  h = (h ^ (h >>> 16)) >>> 0;
  return h % 100 < 22;
}
